  3 │ import hu.bankmonitor.testsupport.BootedApplicationTest;
  4 │ import hu.bankmonitor.testsupport.unmigrated.UnmigratedEntityScan;
  5 │ import org.junit.jupiter.api.DisplayName;
  6 │ import org.junit.jupiter.api.Test;
  7 │ import org.springframework.beans.factory.annotation.Autowired;
  8 │ import org.springframework.boot.WebApplicationType;
  9 │ import org.springframework.boot.builder.SpringApplicationBuilder;
 10 │ import org.springframework.core.io.Resource;
 11 │ import org.springframework.core.io.support.PathMatchingResourcePatternResolver;
 12 │ import org.springframework.jdbc.core.JdbcTemplate;
 13 │ 
 14 │ import java.io.IOException;
 15 │ import java.util.regex.Pattern;
 16 │ 
 17 │ import static org.assertj.core.api.Assertions.assertThat;
 18 │ import static org.assertj.core.api.Assertions.assertThatThrownBy;
 19 │ import static org.assertj.core.api.Assertions.contentOf;
 20 │ 
 21 │ /**
 22 │  * Flyway owns the schema and Hibernate only checks it, from the first commit onwards.
 23 │  *
 24 │  * <p>See design decision 29. There are no tables yet — each later slice ships the
 25 │  * migration for the table it introduces — so what is worth proving now is that the wiring
 26 │  * is live: Flyway really runs, and {@code validate} really refuses a schema that does not
 27 │  * match the entities.
 28 │  *
 29 │  * <p>It extends {@link BootedApplicationTest} for the booted application, not for the
 30 │  * HTTP client that comes with it. Any other {@code @SpringBootTest} annotation here would
 31 │  * be a second configuration and so a second cached context — a whole extra boot to reach
 32 │  * a database the suite has already started.
 33 │  */
 34 │ class FlywayOwnsTheSchemaTest extends BootedApplicationTest {
 35 │ 
 36 │ 	/** Both statements that put rows in a table, tolerating any whitespace between words. */
 37 │ 	private static final Pattern ROW_INSERTING_STATEMENT =
 38 │ 			Pattern.compile("\\b(insert|merge)\\s+into\\b", Pattern.CASE_INSENSITIVE);
 39 │ 
 40 │ 	@Autowired
 41 │ 	private JdbcTemplate jdbc;
 42 │ 
 43 │ 	/**
 44 │ 	 * Asks the database whether Flyway left its history table behind, rather than
 45 │ 	 * asserting {@code spring.flyway.enabled}, which would only restate the default. An
 46 │ 	 * empty migration directory still gets the table, so this holds before the first
 47 │ 	 * {@code V1__} file and keeps holding after it.
 48 │ 	 */
 49 │ 	@Test
 50 │ 	@DisplayName("Flyway runs at startup, even with no migrations to apply")
 51 │ 	void flywayRunsAtStartup() {
 52 │ 		Integer historyTables = jdbc.queryForObject("""
 53 │ 				SELECT count(*) FROM information_schema.tables
 54 │ 				WHERE upper(table_name) = 'FLYWAY_SCHEMA_HISTORY'
 55 │ 				""", Integer.class);
 56 │ 
 57 │ 		assertThat(historyTables).isEqualTo(1);
 58 │ 	}
 59 │ 
 60 │ 	/**
 61 │ 	 * The reason {@code validate} is on from the first commit: a mismatch between an
 62 │ 	 * entity and the schema is a startup failure that names the object it went looking
 63 │ 	 * for, not a surprise at the first query.
 64 │ 	 */
 65 │ 	@Test
 66 │ 	@DisplayName("an entity with no table behind it fails startup, naming the missing table")
 67 │ 	void refusesToStartWhenAnEntityHasNoTable() {
 68 │ 		assertThatThrownBy(FlywayOwnsTheSchemaTest::bootScanningAnUnmigratedEntity)
 69 │ 				.hasStackTraceContaining("Schema validation: missing table [entity_with_no_table]");
 70 │ 	}
 71 │ 
 72 │ 	/**
 73 │ 	 * Seed data in a migration runs everywhere the migration runs, the test suite
 74 │ 	 * included; demo accounts belong in a {@code @Profile("dev")} runner instead. Vacuous
 75 │ 	 * until the first migration lands, and load-bearing for every slice after that.
 76 │ 	 */
 77 │ 	@Test
 78 │ 	@DisplayName("no migration carries seed data")
 79 │ 	void migrationsCarryNoSeedData() throws IOException {
 80 │ 		Resource[] migrations = new PathMatchingResourcePatternResolver()
 81 │ 				.getResources("classpath*:db/migration/**/*.sql");
 82 │ 
 83 │ 		for (Resource migration : migrations) {
 84 │ 			assertThat(contentOf(migration.getURL()))
 85 │ 					.as("%s", migration.getFilename())
 86 │ 					.doesNotContainPattern(ROW_INSERTING_STATEMENT);
 87 │ 		}
 88 │ 	}
 89 │ 
 90 │ 	/**
 91 │ 	 * On its own database, not the shared {@code jdbc:h2:mem:payments} the surrounding
 92 │ 	 * context is still holding open: from the first migration onwards this second
 93 │ 	 * application would otherwise run Flyway against a live context's schema history.
 94 │ 	 */
 95 │ 	private static void bootScanningAnUnmigratedEntity() {
 96 │ 		new SpringApplicationBuilder(GlobalPaymentServiceApplication.class, UnmigratedEntityScan.class)
 97 │ 				.web(WebApplicationType.NONE)
 98 │ 				.properties("spring.datasource.url=jdbc:h2:mem:validate-refuses-unmigrated-entity")
 99 │ 				.run()
100 │ 				.close();
101 │ 	}
102 │ }
 1 │ package hu.bankmonitor.testsupport;
